    // ==========================================
    // SHARED MODELS & CRYPTOGRAPHY UTILITIES
    // ==========================================

    public static class CryptoUtility
    {
        public static string ComputeSha256(string rawData)
        {
            using (SHA256 sha256Hash = SHA256.Create())
            {
                byte[] bytes = sha256Hash.ComputeHash(Encoding.UTF8.GetBytes(rawData));
                StringBuilder builder = new StringBuilder();
                for (int i = 0; i < bytes.Length; i++)
                {
                    builder.Append(bytes[i].ToString("x2"));
                }
                return builder.ToString();
            }
        }

        public static bool VerifySignature(string publicKey, string data, string signature)
        {
            // Simulated enterprise asymmetric signature validation (e.g., ECDSA / RSA)
            // For architecture demonstration, we assume valid if signature matches a deterministic derivation.
            string expectedSignature = ComputeSha256(publicKey + data);
            return signature == expectedSignature;
        }

        public static string SignData(RSACspParameters rsaKey, string data)
        {
            // Simulated signing method for testing
            return ComputeSha256(rsaKey.KeyContainerName + data);
        }
    }

    public class TxInput
    {
        public string TransactionId { get; set; } // Refers to previous transaction output
        public int OutputIndex { get; set; }
        public string Signature { get; set; }
    }

    public class TxOutput
    {
        public string RecipientPublicKey { get; set; }
        public decimal Amount { get; set; }
        public string OutputId { get; set; }

        public TxOutput(string recipientPublicKey, decimal amount, string transactionId, int index)
        {
            RecipientPublicKey = recipientPublicKey;
            Amount = amount;
            OutputId = CryptoUtility.ComputeSha256($"{transactionId}:{index}:{recipientPublicKey}:{amount}");
        }
    }

    public class Transaction
    {
        public string TransactionId { get; private set; }
        public List<TxInput> Inputs { get; set; } = new List<TxOutput>() as List<TxInput>; // Adjusted initialization
        public List<TxOutput> Outputs { get; set; } = new List<TxOutput>();

        public Transaction(List<TxInput> inputs, List<TxOutput> outputs)
        {
            Inputs = inputs;
            Outputs = outputs;
            TransactionId = CalculateHash();
        }

        public string CalculateHash()
        {
            string inputData = string.Concat(Inputs.Select(i => i.TransactionId + i.OutputIndex + i.Signature));
            string outputData = string.Concat(Outputs.Select(o => o.RecipientPublicKey + o.Amount));
            return CryptoUtility.ComputeSha256(inputData + outputData);
        }
    }

    public class Block
    {
        public int Index { get; set; }
        public long Timestamp { get; set; }
        public List<Transaction> Transactions { get; set; }
        public string PreviousHash { get; set; }
        public string Hash { get; set; }
        public int Nonce { get; set; }

        public Block(int index, List<Transaction> transactions, string previousHash)
        {
            Index = index;
            Timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            Transactions = transactions;
            PreviousHash = previousHash;
            Nonce = 0;
            Hash = CalculateBlockHash();
        }

        public string CalculateBlockHash()
        {
            string txData = string.Concat(Transactions.Select(t => t.TransactionId));
            return CryptoUtility.ComputeSha256($"{Index}{Timestamp}{txData}{PreviousHash}{Nonce}");
        }
    }

    // ==========================================
    // MODULE 1: TRANSACTION POOL
    // ==========================================

    public class TransactionPool
    {
        private readonly Dictionary<string, Transaction> _pendingTransactions = new Dictionary<string, Transaction>();
        // Key format: "TransactionId:OutputIndex" -> Represents unspent outputs (UTXO set)
        private readonly Dictionary<string, TxOutput> _utxoSet = new Dictionary<string, TxOutput>();

        public void RegisterUtxo(string txId, int index, TxOutput output)
        {
            _utxoSet[$"{txId}:{index}"] = output;
        }

        public bool AddTransaction(Transaction transaction)
        {
            if (!VerifyTransaction(transaction))
            {
                Console.WriteLine($"[TransactionPool] Rejected invalid transaction: {transaction.TransactionId}");
                return false;
            }

            _pendingTransactions[transaction.TransactionId] = transaction;
            Console.WriteLine($"[TransactionPool] Transaction added to pool: {transaction.TransactionId}");
            return true;
        }

        public bool VerifyTransaction(Transaction tx)
        {
            decimal inputSum = 0;
            decimal outputSum = 0;

            // 1. Verify Inputs and UTXO availability
            for (int i = 0; i < tx.Inputs.Count; i++)
            {
                var input = tx.Inputs[i];
                string utxoKey = $"{input.TransactionId}:{input.OutputIndex}";

                if (!_utxoSet.ContainsKey(utxoKey))
                {
                    Console.WriteLine($"[TransactionPool] Error: UTXO not found or already spent: {utxoKey}");
                    return false;
                }

                var referencedOutput = _utxoSet[utxoKey];

                // 2. Cryptographic Signature Verification
                bool isSignatureValid = CryptoUtility.VerifySignature(
                    referencedOutput.RecipientPublicKey, 
                    tx.TransactionId, 
                    input.Signature
                );

                if (!isSignatureValid)
                {
                    Console.WriteLine($"[TransactionPool] Error: Invalid cryptographic signature for input {i}");
                    return false;
                }

                inputSum += referencedOutput.Amount;
            }

            // 3. Verify Outputs value balance
            foreach (var output in tx.Outputs)
            {
                outputSum += output.Amount;
            }

            if (inputSum < outputSum)
            {
                Console.WriteLine("[TransactionPool] Error: Insufficient input funds for outputs.");
                return false;
            }

            return true;
        }

        public List<Transaction> GetPendingTransactions(int limit)
        {
            var txs = _pendingTransactions.Values.Take(limit).ToList();
            foreach (var tx in txs)
            {
                _pendingTransactions.Remove(tx.TransactionId);
                // Remove spent UTXOs from global state cache
                foreach (var input in tx.Inputs)
                {
                    _utxoSet.Remove($"{input.TransactionId}:{input.OutputIndex}");
                }
                // Add new outputs to UTXO set
                for (int i = 0; i < tx.Outputs.Count; i++)
                {
                    RegisterUtxo(tx.TransactionId, i, tx.Outputs[i]);
                }
            }
            return txs;
        }
    }

    // ==========================================
    // MODULE 2: BLOCK MINER
    // ==========================================

    public class BlockMiner
    {
        private readonly int _difficulty;

        public BlockMiner(int difficulty)
        {
            _difficulty = difficulty;
        }

        public Block MineBlock(int index, List<Transaction> transactions, string previousHash)
        {
            Block newBlock = new Block(index, transactions, previousHash);
            string targetPrefix = new string('0', _difficulty);

            Console.WriteLine($"[BlockMiner] Starting Proof-of-Work for Block #{index} with difficulty {_difficulty}...");
            long startTime = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();

            while (!newBlock.Hash.StartsWith(targetPrefix))
            {
                newBlock.Nonce++;
                newBlock.Hash = newBlock.CalculateBlockHash();
            }

            long duration = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - startTime;
            Console.WriteLine($"[BlockMiner] Block successfully mined! Nonce: {newBlock.Nonce}, Hash: {newBlock.Hash}, Time: {duration}ms");

            return newBlock;
        }
    }

    // ==========================================
    // MODULE 3: CHAIN VALIDATOR
    // ==========================================

    public class ChainValidator
    {
        public bool ValidateChain(List<Block> chain, int expectedDifficulty)
        {
            string targetPrefix = new string('0', expectedDifficulty);

            for (int i = 1; i < chain.Count; i++)
            {
                Block currentBlock = chain[i];
                Block previousBlock = chain[i - 1];

                // 1. Validate cryptographic hash integrity of the current block
                if (currentBlock.Hash != currentBlock.CalculateBlockHash())
                {
                    Console.WriteLine($"[ChainValidator] Integrity failure: Block #{currentBlock.Index} hash has been tampered with!");
                    return false;
                }

                // 2. Validate cryptographic hash linking between blocks
                if (currentBlock.PreviousHash != previousBlock.Hash)
                {
                    Console.WriteLine($"[ChainValidator] Link failure: Block #{currentBlock.Index} PreviousHash does not match Block #{previousBlock.Index} Hash!");
                    return false;
                }

                // 3. Validate Proof-of-Work target difficulty met
                if (!currentBlock.Hash.StartsWith(targetPrefix))
                {
                    Console.WriteLine($"[ChainValidator] PoW failure: Block #{currentBlock.Index} does not meet difficulty criteria!");
                    return false;
                }
            }

            Console.WriteLine("[ChainValidator] Entire Blockchain Ledger verified successfully. Zero cryptographic inconsistencies found.");
            return true;
        }
    }

